package app.gendragoon.cloudssd.mobile;
import android.content.Context;
import android.util.Base64;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.net.URI;

/** The same browser-approval S256 flow as current native GenDragoon. */
final class RedXSession {
    private static String access="",subject="";private static long expires=0;
    static String random(){byte[] value=new byte[32];new SecureRandom().nextBytes(value);return Base64.encodeToString(value,Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING);}
    static JSONObject profile(Context context)throws Exception{String saved=SecurePrefs.get(context,"account");return saved==null?null:new JSONObject(saved);}
    static String receiver(String subject){return CloudApi.sha(("[\"red-xai-receiver/v1\",\"https://red-xai.com\","+JSONObject.quote(subject)+"]").getBytes(StandardCharsets.UTF_8));}
    static JSONObject start()throws Exception{String verifier=random();byte[] challenge=java.security.MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII));CloudApi.Response response=CloudApi.exchange(CloudApi.ISSUER+"/redxai-connect/start","POST",new JSONObject().put("client_id","gendragoon").put("code_challenge",Base64.encodeToString(challenge,Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING)).put("code_challenge_method","S256"),null,131072);if(response.status!=200)throw new CloudApi.Failure(response.status,CloudApi.error(response));JSONObject job=response.json();String device=job.getString("device_code"),code=job.getString("user_code"),url=job.getString("verification_uri");URI uri=URI.create(url);if(!device.matches("[A-Za-z0-9_-]{43}")||code.length()!=8||!"https".equals(uri.getScheme())||!"red-xai.com".equals(uri.getHost())||uri.getPort()!=-1||uri.getUserInfo()!=null||!java.util.Set.of("/redxai-connect","/redxai-connect/","/redxai-connectx").contains(uri.getPath()))throw new java.io.IOException("Invalid Red-XAI approval response.");job.put("verifier",verifier);return job;}
    static JSONObject poll(Context context,JSONObject job)throws Exception{return poll(context,job,null);}
    static JSONObject poll(Context context,JSONObject job,String pendingDeletionSubject)throws Exception{CloudApi.Response response=CloudApi.exchange(CloudApi.ISSUER+"/redxai-connect/token","POST",new JSONObject().put("client_id","gendragoon").put("device_code",job.getString("device_code")).put("code_verifier",job.getString("verifier")),null,131072);if(response.status==428||response.status==429)return null;if(response.status!=200)throw new CloudApi.Failure(response.status,"Red-XAI approval was denied or expired.");return apply(context,response.json(),pendingDeletionSubject,pendingDeletionSubject==null);}
    static synchronized JSONObject apply(Context context,JSONObject tokens,String expected,boolean provision)throws Exception{JSONObject user=tokens.getJSONObject("user");String who=user.getString("sub"),bearer=tokens.getString("access_token"),refresh=tokens.getString("refresh_token");int seconds=tokens.getInt("expires_in");if(!"redx-site-session-v1".equals(tokens.optString("protocol"))||!CloudApi.ISSUER.equals(tokens.optString("issuer"))||!"gendragoon".equals(tokens.optString("client_id"))||!"gendragoon.receiver".equals(tokens.optString("scope"))||!"bearer".equalsIgnoreCase(tokens.optString("token_type"))||!bearer.matches("rxca_[A-Za-z0-9_-]{43}")||!refresh.matches("rxcr_[A-Za-z0-9_-]{43}")||TextChecks.isBlank(who)||who.length()>1024||!user.optBoolean("email_verified")||seconds<1||seconds>3600||expected!=null&&!expected.equals(who))throw new java.io.IOException("Red-XAI identity verification failed.");String receiver=receiver(who);if(provision){CloudApi.Response linked=CloudApi.exchange(CloudApi.ORIGIN+"/v1/receivers/me","PUT",null,bearer,2*1024*1024);JSONObject result=linked.json();if(linked.status!=200||!receiver.equals(result.optString("id"))||!"ready".equals(result.optString("state"))||!"redsecretsxai-png-v1".equals(result.optString("storageFormat")))throw new java.io.IOException("Red-XAI Receiver identity check failed.");}
        JSONObject profile=new JSONObject().put("schema",1).put("issuer",CloudApi.ISSUER).put("subject",who).put("email",user.optString("email","Red-XAI account")).put("receiverId",receiver).put("refresh",refresh);SecurePrefs.put(context,"account",profile.toString());subject=who;access=bearer;expires=System.currentTimeMillis()+seconds*1000L;return profile;}
    static synchronized String access(Context context,String expected,boolean force)throws Exception{JSONObject saved=profile(context);if(saved==null||!expected.equals(saved.optString("subject"))||!receiver(expected).equals(saved.optString("receiverId")))throw new CloudApi.Failure(401,"The connected account changed. Original files were retained.");if(!force&&expected.equals(subject)&&expires>System.currentTimeMillis()+30000&&!access.isEmpty())return access;CloudApi.Response response=CloudApi.exchange(CloudApi.ISSUER+"/redxai-connect/refresh","POST",new JSONObject().put("client_id","gendragoon").put("refresh_token",saved.getString("refresh")),null,131072);if(response.status!=200)throw new CloudApi.Failure(response.status,"Reconnect your Red-XAI app session.");apply(context,response.json(),expected,false);return access;}
    static synchronized String renew(Context context,String expected,String rejected)throws Exception{if(expected.equals(subject)&&!access.equals(rejected)&&expires>System.currentTimeMillis()+30000)return access(context,expected,false);return access(context,expected,true);}
    static synchronized void disconnect(Context context)throws Exception{JSONObject saved=profile(context);SecurePrefs.remove(context,"account");access="";subject="";expires=0;if(saved!=null)try{CloudApi.exchange(CloudApi.ISSUER+"/redxai-connect/revoke","POST",new JSONObject().put("token",saved.getString("refresh")),null,65536);}catch(Exception ignored){/* Local disconnect is complete; no secret is logged. */}}
}
